CREATE TABLE IF NOT EXISTS customers (customer_id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,phone VARCHAR(20) NOT NULL,address TEXT NULL,latitude DECIMAL(10,7) NOT NULL,longitude DECIMAL(10,7) NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_customers_phone(phone)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS orders (order_id INT AUTO_INCREMENT PRIMARY KEY,customer_id INT NOT NULL,order_date DATE NOT NULL,box_count INT NOT NULL,status ENUM('PENDING','PLANNED','DELIVERING','DELIVERED','CANCELLED') NOT NULL DEFAULT 'PENDING',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,CONSTRAINT chk_orders_box_count CHECK(box_count BETWEEN 1 AND 3),CONSTRAINT fk_orders_customer FOREIGN KEY(customer_id) REFERENCES customers(customer_id) ON UPDATE RESTRICT ON DELETE RESTRICT,INDEX idx_orders_customer(customer_id),INDEX idx_orders_date(order_date),INDEX idx_orders_status(status)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS riders (rider_id INT AUTO_INCREMENT PRIMARY KEY,rider_name VARCHAR(150) NOT NULL,phone VARCHAR(20) NULL,is_available BOOLEAN NOT NULL DEFAULT TRUE,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS route_plans (route_plan_id INT AUTO_INCREMENT PRIMARY KEY,plan_date DATE NOT NULL,start_time TIME NOT NULL DEFAULT '11:30:00',estimated_finish_time TIME NULL,rider_count INT NULL,total_distance_km DECIMAL(10,2) NULL,total_delivery_cost DECIMAL(10,2) NULL,total_revenue DECIMAL(10,2) NULL,total_food_cost DECIMAL(10,2) NULL,estimated_profit DECIMAL(10,2) NULL,status ENUM('GENERATED','SELECTED','REJECTED') NOT NULL DEFAULT 'GENERATED',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_route_plans_date(plan_date),INDEX idx_route_plans_status(status)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS delivery_jobs (delivery_job_id INT AUTO_INCREMENT PRIMARY KEY,route_plan_id INT NOT NULL,rider_id INT NULL,job_code VARCHAR(64) NOT NULL,total_orders INT NOT NULL DEFAULT 0,total_boxes INT NOT NULL DEFAULT 0,total_distance_km DECIMAL(10,2) NULL,estimated_duration_min INT NULL,estimated_start_time TIME NULL,estimated_finish_time TIME NULL,delivery_cost DECIMAL(10,2) NULL,status ENUM('WAITING','DELIVERING','COMPLETED') NOT NULL DEFAULT 'WAITING',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_delivery_jobs_code(job_code),CONSTRAINT chk_delivery_jobs_orders CHECK(total_orders BETWEEN 0 AND 3),CONSTRAINT fk_jobs_plan FOREIGN KEY(route_plan_id) REFERENCES route_plans(route_plan_id) ON UPDATE RESTRICT ON DELETE RESTRICT,CONSTRAINT fk_jobs_rider FOREIGN KEY(rider_id) REFERENCES riders(rider_id) ON UPDATE RESTRICT ON DELETE SET NULL,INDEX idx_jobs_plan(route_plan_id),INDEX idx_jobs_rider(rider_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS delivery_job_orders (delivery_job_order_id INT AUTO_INCREMENT PRIMARY KEY,delivery_job_id INT NOT NULL,order_id INT NOT NULL,stop_sequence INT NOT NULL,distance_from_previous_km DECIMAL(10,2) NULL,travel_time_from_previous_min INT NULL,estimated_arrival_time TIME NULL,actual_arrival_time TIME NULL,delivery_status ENUM('WAITING','DELIVERING','DELIVERED') NOT NULL DEFAULT 'WAITING',UNIQUE KEY uq_job_order(delivery_job_id,order_id),UNIQUE KEY uq_job_sequence(delivery_job_id,stop_sequence),CONSTRAINT fk_job_orders_job FOREIGN KEY(delivery_job_id) REFERENCES delivery_jobs(delivery_job_id) ON UPDATE RESTRICT ON DELETE RESTRICT,CONSTRAINT fk_job_orders_order FOREIGN KEY(order_id) REFERENCES orders(order_id) ON UPDATE RESTRICT ON DELETE RESTRICT,INDEX idx_job_orders_job(delivery_job_id),INDEX idx_job_orders_order(order_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS shop_settings (setting_id INT PRIMARY KEY,shop_name VARCHAR(150) NOT NULL,latitude DECIMAL(10,7) NOT NULL,longitude DECIMAL(10,7) NOT NULL,delivery_start_time TIME NOT NULL DEFAULT '11:30:00',delivery_deadline TIME NOT NULL DEFAULT '12:30:00',max_orders_per_rider INT NOT NULL DEFAULT 3,rider_speed_kmh DECIMAL(8,2) NOT NULL DEFAULT 30,box_sale_price DECIMAL(10,2) NOT NULL DEFAULT 65,box_food_cost DECIMAL(10,2) NOT NULL DEFAULT 40,rider_base_cost DECIMAL(10,2) NOT NULL DEFAULT 15,rider_cost_per_km DECIMAL(10,2) NOT NULL DEFAULT 4,CONSTRAINT chk_settings_max_orders CHECK(max_orders_per_rider BETWEEN 1 AND 3)) ENGINE=InnoDB;